// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(this));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        vm.prank(caller);
        try c.withdrawAll(caller) {} catch {}
        uint256 balAfter = address(c).balance;
        bool isOwner = caller == c.owner();
        bool drained = balAfter == 0 && balBefore > 0;
        assertTrue(isOwner ? drained : !drained);
    }
}
